<template>
  <main class="min-h-screen bg-gray-950 p-4 text-white md:p-8"><section class="mx-auto max-w-3xl rounded-lg border border-cyan-500/30 bg-gray-900 p-6"><div v-if="error" class="rounded border border-red-500/40 bg-red-500/10 p-4 text-red-100">{{ error }}</div><template v-else-if="quotation"><p class="text-sm text-cyan-300">{{ quotation.code }}</p><h1 class="mt-1 text-2xl font-semibold">{{ quotation.title }}</h1><p class="mt-2 text-gray-400">{{ quotation.description }}</p><p class="mt-4 text-sm text-amber-200">Prazo: {{ quotation.response_deadline }}</p><form class="mt-6 space-y-5" @submit.prevent="save(true)"><div class="grid gap-3 md:grid-cols-2"><input v-model="form.supplier_name" class="input" placeholder="Nome ou razão social" required><input v-model="form.supplier_document" class="input" placeholder="CPF/CNPJ"><input v-model="form.supplier_email" class="input" type="email" placeholder="E-mail"><input v-model="form.supplier_phone" class="input" placeholder="Telefone"></div><section v-for="item in quotation.items" :key="item.id" class="rounded border border-gray-700 p-4"><p class="font-medium">{{ item.quantity }} {{ item.unit }} - {{ item.description }}</p><p class="mt-1 text-sm text-gray-400">{{ item.specification }}</p><div class="mt-3 grid gap-3 md:grid-cols-2"><input v-model.number="line(item.id).unit_price" class="input" type="number" min="0" step="0.01" placeholder="Preço unitário"><input v-model="line(item.id).notes" class="input" placeholder="Observação"></div></section><div class="grid gap-3 md:grid-cols-2"><input v-model.number="form.freight_amount" class="input" type="number" min="0" step="0.01" placeholder="Frete"><input v-model="form.payment_terms" class="input" placeholder="Condições de pagamento"><input v-model="form.delivery_terms" class="input" placeholder="Prazo/condições de entrega"><textarea v-model="form.notes" class="input" placeholder="Observações"/></div><div><label class="text-sm text-gray-300">Anexar proposta ou orçamento (PDF/imagem)<input class="mt-2 block text-sm" type="file" accept="application/pdf,image/*" @change="upload"></label></div><div class="flex justify-end gap-2"><button type="button" class="rounded border border-gray-600 px-4 py-2 text-gray-200" @click="save(false)">Salvar rascunho</button><button class="rounded bg-cyan-500 px-4 py-2 font-semibold text-gray-950" type="submit">Enviar proposta</button></div></form></template><p v-else class="text-gray-400">Carregando cotação...</p></section></main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import api from '@/utils/api';
import { useRoute } from 'vue-router';
const route = useRoute(); const quotation = ref(null); const error = ref(''); const form = ref({ supplier_name: '', supplier_document: '', supplier_email: '', supplier_phone: '', freight_amount: 0, payment_terms: '', delivery_terms: '', notes: '', items: [] });
function line(id) { let item = form.value.items.find((candidate) => candidate.procurement_item_id === id); if (!item) { item = { procurement_item_id: id, unit_price: null, notes: '' }; form.value.items.push(item); } return item; }
async function load() { try { const { data } = await api.get(`/public/supplier-quotes/${route.params.token}`); quotation.value = data; if (data.quote) { form.value = { ...form.value, ...data.quote, items: data.quote.items?.map((item) => ({ procurement_item_id: item.procurement_item_id, unit_price: Number(item.unit_price), notes: item.notes })) || [] }; } else { form.value.supplier_name = data.supplier_name || ''; } } catch (requestError) { error.value = requestError.response?.status === 410 ? 'Este link expirou ou foi encerrado.' : 'Não foi possível abrir esta cotação.'; } }
async function save(submit) { try { await api.post(`/public/supplier-quotes/${route.params.token}`, { ...form.value, submit }); await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Não foi possível salvar a proposta.'; } }
async function upload(event) { const file = event.target.files?.[0]; if (!file) return; const payload = new FormData(); payload.append('file', file); try { await api.post(`/public/supplier-quotes/${route.params.token}/attachments`, payload); } catch { error.value = 'Não foi possível enviar o anexo.'; } }
onMounted(load);
</script>
<style scoped>.input { width: 100%; border: 1px solid rgb(75 85 99); border-radius: .5rem; background: rgb(31 41 55); color: white; padding: .65rem .75rem; }</style>
